	local cy = Math.Cos(yaw * 0.5)
	local sy = Math.Sin(yaw * 0.5)
	local cp = Math.Cos(pitch * 0.5)
	local sp = Math.Sin(pitch * 0.5)
	local cr = Math.Cos(roll * 0.5)
	local sr = Math.Sin(roll * 0.5)
