function Quat:slerp(b, t)
	local d = self:dot(b)
	local bx = b.x
	local by = b.y
	local bz = b.z
	local bw = b.w
	if d < 0 then
		d = -d
		bx = -bx
		by = -by
		bz = -bz
		bw = -bw
	end
	if d > 0.9995 then
		return Quat.new(
			self.x + (bx - self.x) * t,
			self.y + (by - self.y) * t,
			self.z + (bz - self.z) * t,
			self.w + (bw - self.w) * t
		):normalize()
	end
	local theta = Math.Atan2(Math.Sqrt(1.0 - d * d), d)
	local sinT = Math.Sin(theta)
	local s0 = Math.Sin((1.0 - t) * theta) / sinT
	local s1 = Math.Sin(t * theta) / sinT
