		return Quat.new(
			(m.m[6 + 1] - m.m[9 + 1]) * s,
			(m.m[8 + 1] - m.m[2 + 1]) * s,
			(m.m[1 + 1] - m.m[4 + 1]) * s,
			0.25 / s
