			(m.m[1 + 1] + m.m[4 + 1]) / s,
			0.25 * s,
			(m.m[6 + 1] + m.m[9 + 1]) / s,
			(m.m[8 + 1] - m.m[2 + 1]) / s
		)
	else
		local s = 2.0 * Math.Sqrt(1.0 + m.m[10 + 1] - m.m[0 + 1] - m.m[5 + 1])
		return Quat.new(
			(m.m[8 + 1] + m.m[2 + 1]) / s,
			(m.m[6 + 1] + m.m[9 + 1]) / s,
			0.25 * s,
			(m.m[1 + 1] - m.m[4 + 1]) / s
