function SdfNode:paint(rgb, metallic, roughness)
	return SdfNode.unary(lub.mesh.PAINT, {
		math.fmod(Math.Floor(rgb / 65536.0), 256) / 255.0,
		math.fmod(Math.Floor(rgb / 256.0), 256) / 255.0,
		__tcs_irem(rgb, 256) / 255.0,
		metallic or 0.0,
		roughness or 0.8,
	}, self)
