function TextGlyph.new()
	local self = setmetatable({}, TextGlyph)
	__tcs_instances[self] = TextGlyph
	self.u = 0
	self.v = 0
	self.w = 0
	self.h = 0
	self.xoff = 0
	self.yoff = 0
	self.advance = 0
