Text = {}
Text.__index = Text

function Text.new(key, ttfPath, px, atlasSize)
	local self = setmetatable({}, Text)
	__tcs_instances[self] = Text
	self.px = 0
	self.ascent = 0
	self.descent = 0
	self.line_height = 0
	self.ttf_path = nil
	self.atlas = nil
	self.atlas_w = 0
	self.atlas_h = 0
	self.pixels = nil
	self.glyphs = {}
	self.missing = {}
	self.pen_x = 1
	self.pen_y = 1
	self.row_h = 0
	self.ttf_path = ttfPath
	self.px = px
	local size = atlasSize or 256
	self.atlas_w = size
	self.atlas_h = size
	self.pixels = {}
	local i = 0
	while i < self.atlas_w * self.atlas_h * 4 do
		table.insert(self.pixels, 0)
		i = i + 1
	end
	local m = lub.font.metrics(self:ttf())
	self.ascent = m.ascent * px
	self.descent = m.descent * px
	self.line_height = (m.ascent - m.descent + m.line_gap) * px
	self.atlas = Atlas.from_pixels(key, self.atlas_w, self.atlas_h, self.pixels)
	return self
end

function Text:ttf()
	local b
	local _
	b, _, _, _ = lub.io.load_bytes(self.ttf_path)
	return b
end

function Text.each_codepoint(s, f)
	for _, r in utf8.codes(s) do
		f(r)
	end
end

function Text:ensure_glyph(cp)
	local cached
	local __tcs_cond3
	local __tcs_found, __tcs_v = Dict.TryGet(self.glyphs, cp, nil)
	cached = __tcs_v
	__tcs_cond3 = __tcs_found
	if __tcs_cond3 then
		return cached
	end
	if Dict.ContainsKey(self.missing, cp) then
		return nil
	end
	local gb = lub.font.glyph(self:ttf(), cp, self.px)
	if gb == nil then
		self.missing[cp] = true
		return nil
	end
	local u = 0
	local v = 0
	if gb.bytes ~= nil and gb.w > 0 and gb.h > 0 then
		if self.pen_x + gb.w + 1 > self.atlas_w then
			self.pen_x = 1
			self.pen_y = self.pen_y + self.row_h + 1
			self.row_h = 0
		end
		if self.pen_y + gb.h + 1 > self.atlas_h then
			print("lubx.Text: atlas full, glyph dropped: " .. cp)
			self.missing[cp] = true
			return nil
		end
		u = self.pen_x
		v = self.pen_y
		local src = 0
		local row = 0
		while row < gb.h do
			local dst = ((v + row) * self.atlas_w + u) * 4
			local i = 0
			while i < gb.w do
				local a = gb.bytes:get(src)
				src = src + 1
				self.pixels[dst + 1] = 255
				self.pixels[dst + 1 + 1] = 255
				self.pixels[dst + 2 + 1] = 255
				self.pixels[dst + 3 + 1] = a
				dst = dst + 4
				i = i + 1
			end
			row = row + 1
		end
		self.pen_x = self.pen_x + gb.w + 1
		if gb.h > self.row_h then
			self.row_h = gb.h
		end
		self.atlas:update_pixels(self.pixels)
	end
	local g
	local __tcs_init = TextGlyph.new()
	__tcs_init.u = u
	__tcs_init.v = v
	__tcs_init.w = gb.w
	__tcs_init.h = gb.h
	__tcs_init.xoff = gb.xoff
	__tcs_init.yoff = gb.yoff
	__tcs_init.advance = gb.advance
	g = __tcs_init
	self.glyphs[cp] = g
	return g
end

function Text:width(s, scale)
	local sum = 0.0
	local prev = -1
	Text.each_codepoint(s, function(cp)
		local g = self:ensure_glyph(cp)
		if g == nil then
			return
		end
		if prev >= 0 then
			sum = sum + lub.font.kern(self:ttf(), prev, cp) * self.px
		end
		sum = sum + g.advance
		prev = cp
	end)
	return sum * (scale or 1.0)
end

function Text:draw(batch, s, x, y, tint, scale)
	local sc = scale or 1.0
	local pen = x
	local prev = -1
	Text.each_codepoint(s, function(cp)
		local g = self:ensure_glyph(cp)
		if g == nil then
			return
		end
		if prev >= 0 then
			pen = pen + lub.font.kern(self:ttf(), prev, cp) * self.px * sc
		end
		if g.w > 0 then
			batch:quad(
				self.atlas,
				Rect.new(g.u, g.v, g.w, g.h),
				pen + g.xoff * sc,
				y + g.yoff * sc,
				g.w * sc,
				g.h * sc,
				tint
			)
		end
		pen = pen + g.advance * sc
		prev = cp
	end)
end
return {
	Assets = Assets,
	Atlas = Atlas,
	Bones = Bones,
	Camera = Camera,
	Camera2d = Camera2d,
	Camera3d = Camera3d,
	Camera3dOpts = Camera3dOpts,
	Color = Color,
	Draw3dOpts = Draw3dOpts,
	FixedStep = FixedStep,
	FpsMeter = FpsMeter,
	GlyphEntry = GlyphEntry,
	Mat4 = Mat4,
	MathUtil = MathUtil,
	Mesh3d = Mesh3d,
	MeshText = MeshText,
	Quat = Quat,
	Rand = Rand,
	Rect = Rect,
	Renderer3d = Renderer3d,
	Renderer3dAa = Renderer3dAa,
	Renderer3dBloom = Renderer3dBloom,
	Renderer3dDrawCmd = Renderer3dDrawCmd,
	Renderer3dFog = Renderer3dFog,
	Renderer3dLight = Renderer3dLight,
	Renderer3dOutline = Renderer3dOutline,
	Renderer3dShadow = Renderer3dShadow,
	Renderer3dSky = Renderer3dSky,
	Renderer3dSsao = Renderer3dSsao,
	Sdf = Sdf,
	SdfNode = SdfNode,
	SdfPanel = SdfPanel,
	Sfx = Sfx,
	Shapes = Shapes,
	Shapes3d = Shapes3d,
	SpriteBatch = SpriteBatch,
	SpriteBucket = SpriteBucket,
	Text = Text,
	TextGlyph = TextGlyph,
	Vec2 = Vec2,
	Vec3 = Vec3,
	Vec4 = Vec4,
}
